WITH dated AS (
 SELECT player_api_id, overall_rating, defensive_work_rate,
 ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) rn
 FROM Player_Attributes WHERE date <= '2013-07-12'
), eligible AS (
 SELECT player_api_id, overall_rating FROM dated WHERE rn=1 AND defensive_work_rate IN ('low','medium','high')
), avg_rating AS (SELECT AVG(overall_rating) avg_overall FROM eligible), donovan AS (
 SELECT e.overall_rating FROM eligible e JOIN Player p ON p.player_api_id=e.player_api_id WHERE p.player_name='Landon Donovan'
)
SELECT ROUND(100.0*(d.overall_rating-a.avg_overall)/a.avg_overall,2) AS percentage_higher
FROM donovan d CROSS JOIN avg_rating a;

