WITH race AS (
  SELECT raceId FROM races WHERE year = 1957 AND name = 'British Grand Prix'
), race_results AS (
  SELECT res.driverId, s.status
  FROM results res
  JOIN race r ON res.raceId = r.raceId
  JOIN status s ON res.statusId = s.statusId
), classified AS (
  SELECT COUNT(*) AS classified_count FROM race_results WHERE status = 'Finished' OR status LIKE '+%'
)
SELECT ROUND(100.0 * classified_count / (SELECT COUNT(*) FROM race_results), 2) AS percentage
FROM classified;

